import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.DH50UWNB.js";const c=JSON.parse('{"title":"wake CLI","description":"Every wake CLI command and its options: setup, login, init, sync, watch, connect, doctor, evidence, upgrade and hook, with exit codes and environment.","frontmatter":{"description":"Every wake CLI command and its options: setup, login, init, sync, watch, connect, doctor, evidence, upgrade and hook, with exit codes and environment."},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1794486787000}'),n={name:"reference/cli.md"};function h(o,e,d,l,r,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="wake-cli" tabindex="-1">wake CLI <a class="header-anchor" href="#wake-cli" aria-label="Permalink to &quot;wake CLI&quot;">​</a></h1><p><code>wake</code> connects a repository&#39;s plan to a Wake project, keeps it in sync and connects your coding agents. <code>wake help &lt;command&gt;</code> prints any command&#39;s options; <code>wake --version</code> prints the version.</p><p>A usage error exits <code>2</code>; any other failure exits <code>1</code> with one <code>wake: ...</code> line. The CLI never prints a token.</p><h2 id="which-server-a-command-uses" tabindex="-1">Which server a command uses <a class="header-anchor" href="#which-server-a-command-uses" aria-label="Permalink to &quot;Which server a command uses&quot;">​</a></h2><p><code>wake sync</code>, <code>watch</code>, <code>doctor</code>, <code>evidence</code> and the agents&#39; hooks use the server the repository&#39;s <code>.wake/config.json</code> names. The commands that connect a repository choose one:</p><ul><li><code>wake login</code> and <code>wake setup --agent</code> use <code>--server</code>, then <code>WAKE_SERVER</code>, then the server the installer recorded on this machine, then the address a local installation serves by default (see <a href="/wake-dist/docs/start/install#your-wake-url-and-installation-directory">Your Wake URL</a>).</li><li>The guided <code>wake setup</code> uses <code>--server</code>, then the repository&#39;s server, the recorded one, the only server you are logged in to, then <code>WAKE_SERVER</code>; else it asks.</li><li><code>wake init</code> uses the stored login that matches <code>--server</code> and <code>--workspace</code>.</li></ul><p>So on the machine where you installed Wake, plain <code>wake login</code> finds your Wake URL. On any other machine, run <code>wake login --server &lt;your Wake URL&gt;</code> once. The address must use <code>https</code>; plain <code>http</code> is allowed only for <code>localhost</code>, <code>127.0.0.1</code> and <code>[::1]</code>.</p><h2 id="setup" tabindex="-1">setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;setup&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--agent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--workspace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--project </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--no-browser]</span></span></code></pre></div><p>Connects this repository and a coding agent in one command; it never commits. Without <code>--agent</code>, the choices are made in the browser: the server, the project and the agent. With <code>--agent</code> (<code>claude-code</code>, <code>opencode</code>, <code>pi</code> or <code>codex</code>), only the login is asked. Running it again changes nothing that is already set up, and resumes where a failed step stopped. See <a href="/wake-dist/docs/start/first-project#connect-a-repository">Your first project</a>.</p><h2 id="login" tabindex="-1">login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;login&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--workspace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--no-browser]</span></span>\n<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with-token</span></span></code></pre></div><p>Signs the CLI in and stores a personal access token of one workspace in the OS keychain, or in a file readable only by you when there is no keychain. In a terminal it signs in with the browser; <code>--with-token</code>, or a token piped on standard input, reads a token instead. See <a href="/wake-dist/docs/start/cli#sign-in">Install the CLI and sign in</a>.</p><h2 id="init" tabindex="-1">init <a class="header-anchor" href="#init" aria-label="Permalink to &quot;init&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--workspace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--project </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--default-branch </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--plan </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">metho</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--no-sync]</span></span></code></pre></div><p>Connects the repository to a Wake project, creating it when it does not exist, writes <code>.wake/config.json</code> (commit it) and syncs the plan. <code>--plan</code> is <code>openspec</code>, <code>spec-kit</code> or <code>odd</code>; by default it is detected. <code>--no-sync</code> connects without syncing.</p><h2 id="sync" tabindex="-1">sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;sync&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--allow-empty]</span></span></code></pre></div><p>Reads the plan, writes a stable <code>wake:</code> id on each task that needs one (OpenSpec only; Wake writes nothing into Spec Kit or ODD files) and sends the plan this branch owns: the default branch&#39;s is committed, other branches&#39; are provisional. It also sends the repository&#39;s <a href="/wake-dist/docs/use/versions">version tags</a>. Nothing is written or sent when a file has errors; each is printed as <code>path:line: message</code>.</p><p>Before what the server changed, it may print two notes; neither stops the sync:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 tasks had text longer than Wake keeps and were shortened; run `wake doctor` to list them.</span></span>\n<span class="line"><span>3 open tasks have no &quot;Done when:&quot; line, so Wake cannot show when they are done; run `wake doctor` to list them.</span></span></code></pre></div><p>The second counts open checkbox tasks without a <code>Done when:</code> line (done tasks and ODD table rows never count); add one under each task so its detail says when it is finished. <code>wake watch</code>, <code>wake init</code> and <code>wake setup</code> print the same notes.</p><p>On the default branch, a plan with no committed work would remove every committed phase from Wake; the server refuses it unless <code>--allow-empty</code> confirms it. See <a href="/wake-dist/docs/agents/openspec">OpenSpec</a>, <a href="/wake-dist/docs/agents/spec-kit">Spec Kit</a>, <a href="/wake-dist/docs/agents/odd">ODD</a> and <a href="/wake-dist/docs/agents/milestones">Milestones and task text</a>.</p><h2 id="watch" tabindex="-1">watch <a class="header-anchor" href="#watch" aria-label="Permalink to &quot;watch&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span></span></code></pre></div><p>Syncs now, then again 300 ms after the last change to the plan, the git branch or a tag. Failed syncs are retried after 1 s, 2 s, 4 s and so on, up to 60 s. Stop it with Ctrl-C.</p><h2 id="connect-and-disconnect" tabindex="-1">connect and disconnect <a class="header-anchor" href="#connect-and-disconnect" aria-label="Permalink to &quot;connect and disconnect&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disconnect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>connect</code> installs or updates an agent&#39;s Wake adapter in this repository: Wake&#39;s MCP server, the hooks that run <code>wake hook</code>, and the agent&#39;s skills and commands. It merges into existing configuration and never writes a token; commit the files. <code>disconnect</code> removes what <code>connect</code> added, keeping files you edited. See <a href="/wake-dist/docs/agents/">Agents and plans</a>.</p><h2 id="doctor" tabindex="-1">doctor <a class="header-anchor" href="#doctor" aria-label="Permalink to &quot;doctor&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--agent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p>Checks, changing nothing: the repository&#39;s <code>.wake/config.json</code>, its plan method and files, the plan&#39;s text, the open tasks without a <code>Done when:</code> line (up to 20 listed as <code>path:line</code>), a login that can read its project, the server&#39;s version against the CLI&#39;s, the MCP endpoint, <code>wake</code> on <code>PATH</code>, and each connected agent&#39;s files. Each line starts with <code>✓</code>, <code>✗</code> or <code>!</code> (a warning), and a failure ends with its fix. It exits <code>0</code> when every check passes or only warns, and <code>1</code> when one fails. See <a href="/wake-dist/docs/reference/troubleshooting">Troubleshooting</a>.</p><h2 id="evidence" tabindex="-1">evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;evidence&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> evidence</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--kind </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p>Attaches a file as evidence of a task, acting as the claim your user holds on it with that session. Images (<code>.png</code>, <code>.jpg</code>, <code>.jpeg</code>, <code>.webp</code>, <code>.gif</code>) and text (<code>.txt</code>, <code>.log</code>), at most 10 MiB; <code>-</code> reads text from standard input. <code>--kind</code> is <code>screenshot</code>, <code>test_report</code>, <code>log</code>, <code>link</code>, <code>note</code> or <code>other</code>; <code>--title</code> takes up to 200 characters. Your agent usually runs it.</p><h2 id="upgrade" tabindex="-1">upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;upgrade&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x.y.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">z</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--check] [--no-server]</span></span></code></pre></div><p><code>wake upgrade</code> installs the version the server of the current repository recommends, or the newest <a href="https://github.com/dalodev/wake-dist/releases" target="_blank" rel="noreferrer">release</a> outside a connected repository (the newest prerelease for a prerelease CLI). It downloads that release&#39;s <code>wake-cli.tgz</code>, <code>install.sh</code>, <code>SHA256SUMS</code> and <code>SHA256SUMS.sig</code>, verifies the signature with the release key built into the CLI and both files against <code>SHA256SUMS</code> (no <code>ssh-keygen</code> needed), checks that <code>install.sh</code> carries the version asked for, so an older release&#39;s signed files served under a newer tag are refused, and installs the verified file. A release that is not signed, does not verify or has no <code>wake-cli.tgz</code> installs nothing.</p><table tabindex="0"><thead><tr><th>Installed with</th><th><code>wake upgrade</code> runs or prints</th></tr></thead><tbody><tr><td><code>npm install --global</code></td><td><code>npm install --global &lt;the verified wake-cli.tgz&gt;</code></td></tr><tr><td><code>pnpm add --global</code></td><td><code>pnpm add --global &lt;the verified wake-cli.tgz&gt;</code>, from a copy kept in <code>wake/cli/</code> of the configuration directory</td></tr><tr><td><code>npx</code></td><td>prints <code>npx --yes --package https://github.com/dalodev/wake-dist/releases/download/v&lt;version&gt;/wake-cli.tgz wake</code>; installs nothing</td></tr></tbody></table><ul><li><code>wake upgrade --check</code> only says whether a newer CLI exists.</li><li><code>wake upgrade --version 1.2.0</code> installs that CLI version, even an older one.</li><li>A CLI newer than its server installs nothing and prints the <code>wake upgrade --version</code> command that matches the server.</li></ul><p>On the machine that hosts Wake (the directory in <code>WAKE_SERVER_DIR</code>, else the one the installer recorded, else the default installation directory), <code>wake upgrade</code> first runs <code>wake-server upgrade</code> there, which upgrades the server and the web app, then upgrades the CLI. If the server upgrade fails, the CLI is still upgraded and the command exits <code>1</code>. <code>--no-server</code> skips the server, and <code>--version</code> and <code>--check</code> act on the CLI only and never touch it. A remote server is upgraded by whoever runs it.</p><h3 id="automatic-upgrade" tabindex="-1">Automatic upgrade <a class="header-anchor" href="#automatic-upgrade" aria-label="Permalink to &quot;Automatic upgrade&quot;">​</a></h3><p>When the server of the repository recommends a newer CLI, the next agent session start runs <code>wake upgrade --version &lt;recommended&gt;</code> in the background and tells the agent. Since it passes <code>--version</code>, it never upgrades a server. It runs only:</p><ul><li>for a CLI installed with <code>npm install --global</code> or <code>pnpm add --global</code>, never under <code>npx</code>;</li><li>when <code>CI</code> is not set and <code>WAKE_AUTO_UPGRADE</code> is not <code>off</code>;</li><li>at most once a day for the same version, so a failing install does not run at every session.</li></ul><p>Its output goes to <code>auto-upgrade.log</code> in Wake&#39;s configuration directory (<code>~/.config/wake/auto-upgrade.log</code>, or under <code>XDG_CONFIG_HOME</code>).</p><h2 id="hook" tabindex="-1">hook <a class="header-anchor" href="#hook" aria-label="Permalink to &quot;hook&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hook</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session-start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">session-end</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tool-use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--agent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Runs from the hooks <code>wake connect</code> installs; you do not run it yourself. <code>session-start</code> syncs and prints the session&#39;s context, <code>session-end</code> releases the session&#39;s claims, and <code>tool-use</code> reports each tool&#39;s name (never its arguments or output) and the new commits. It always exits <code>0</code>: when Wake is offline or you are not logged in, it prints one <code>Wake:</code> line instead.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>WAKE_SERVER</code></td><td>The server <code>wake login</code> and <code>wake setup --agent</code> use without <code>--server</code> (see <a href="#which-server-a-command-uses">Which server a command uses</a>); the only one <code>WAKE_TOKEN</code> is sent to</td></tr><tr><td><code>WAKE_TOKEN</code></td><td>A personal access token to use instead of a stored login, for CI; see <a href="/wake-dist/docs/start/cli#in-ci">In CI</a></td></tr><tr><td><code>WAKE_CREDENTIALS</code></td><td><code>file</code> stores the login in a file instead of the OS keychain</td></tr><tr><td><code>WAKE_AUTO_UPGRADE</code></td><td><code>off</code> keeps the agent session start from upgrading the CLI</td></tr><tr><td><code>WAKE_ADAPTER_UPDATES</code></td><td><code>off</code> keeps the agent session start from updating the adapter&#39;s files; it then says to run <code>wake connect &lt;agent&gt;</code></td></tr><tr><td><code>WAKE_NO_UPDATE_CHECK</code></td><td><code>1</code> stops the daily check that suggests <code>wake upgrade</code>; it is off when <code>CI</code> is set</td></tr><tr><td><code>WAKE_SERVER_DIR</code></td><td>The local installation&#39;s directory, for <code>wake upgrade</code> (default: the one the installer recorded, else the default installation directory)</td></tr><tr><td><code>CI</code></td><td>Any value turns off the automatic upgrade and the daily update check</td></tr></tbody></table>',50)])])}const g=s(n,[["render",h]]);export{c as __pageData,g as default};
